<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/force_ssl_controls.php';
function provider_force_ssl_controls_label(string $status):string {return match($status){'observed'=>'Desired flag observed after the request','not_sent'=>'Refused before provider dispatch','interrupted'=>'Interrupted request — operator recovery required',default=>'Change requested — effect is uncertain'};}
function provider_force_ssl_controls_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="force-ssl-changes"><h2>Change a Force SSL flag</h2><p>Request a change for an assigned website, then separately read its reported flag. A reported match does not prove this request caused it, or check the certificate or whether HTTPS works. Client sharing stays separate.</p>';
    try{
        if(!provider_force_ssl_ready()||!provider_operations_ready()){echo '<p>Prepare Force SSL observations and provider operations first.</p></section>';return;}
        if(!provider_force_ssl_controls_ready()){echo '<form method="post" data-force-ssl-control-prepare>';admin_action('provider_force_ssl_control_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Enable Force SSL change requests</button></form></section>';return;}
        $page=max(1,min(10000,(int)($_GET['force_ssl_control_page']??1)));$links=all('SELECT l.id,l.profile_id,l.package_id,c.name AS client_name FROM '.table('provider_package_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.id LIMIT 20 OFFSET '.(($page-1)*20));
        foreach($links as $link){echo '<article class="workspace-card" data-force-ssl-control-package><h3>'.esc($link['client_name']).' · Package '.esc((string)$link['package_id']).'</h3>';
            try{$form=staff_locked(fn()=>staff_transaction(function()use($link):array{if(!provider_force_ssl_controls_ready())throw new RuntimeException('Force SSL change storage is unavailable.');$pending=provider_force_ssl_controls_pending($link['profile_id'],(int)$link['package_id']);$r=provider_force_ssl_latest($link['id']);$binding=provider_force_ssl_binding($link['id']);if(!$r)throw new RuntimeException('Save a Force SSL observation first.');[, $anchor]=provider_force_ssl_controls_precondition($link['id'],$r['id'],$binding->sha256);return ['pending'=>$pending,'binding'=>$binding,'anchor'=>$anchor];}));
                if($form['pending'])echo '<p>A prior request for this package remains unresolved. Use its history below; another change cannot be sent.</p>';
                else{$desired=!$form['anchor']['value'];echo '<form method="post" data-force-ssl-control-change>';admin_action('provider_force_ssl_control_change');foreach(['request_id'=>bin2hex(random_bytes(16)),'link_id'=>$link['id'],'anchor_id'=>$form['anchor']['id'],'binding_sha256'=>$form['binding']->sha256,'desired'=>$desired?'true':'false'] as $name=>$value)echo '<input type="hidden" name="'.$name.'" value="'.esc($value).'">';echo '<p>Latest saved flag: <strong>'.($form['anchor']['value']?'reported set':'reported false').'</strong>. Requested flag: <strong>'.($desired?'true':'false').'</strong>.</p><label class="check"><input type="checkbox" name="reviewed" value="1" required> I reviewed this website and approve this one request.</label>';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Request flag '.($desired?'true':'false').'</button></form>';}
            }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="hint">'.esc($e->getMessage()).'</p>';}echo '</article>';
        }
        echo '<nav class="button-row" aria-label="Force SSL change assignments">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['force_ssl_control_page'=>$page-1])).'#force-ssl-changes">Previous assignments</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['force_ssl_control_page'=>$page+1])).'#force-ssl-changes">More assignments</a>';echo '</nav>';
        $historyPage=max(1,min(10000,(int)($_GET['force_ssl_change_history_page']??1)));echo '<h3>Change request history</h3>';
        foreach(all('SELECT id FROM '.table('provider_force_ssl_changes').' ORDER BY grant_seq DESC LIMIT 20 OFFSET '.(($historyPage-1)*20)) as $row){$view=staff_locked(fn()=>staff_transaction(fn()=>provider_force_ssl_controls_summary($row['id'])));echo '<article class="workspace-message" data-force-ssl-control-history><h4>'.esc(provider_force_ssl_controls_label($view['status'])).'</h4><p>Package '.esc((string)$view['package_id']).' · Requested flag '.($view['requested_value']?'true':'false').' · '.esc(gmdate('Y-m-d H:i:s',$view['requested_epoch'])).' UTC</p>';
            if($view['status']==='interrupted'){
                echo '<p>The local dispatch record is missing. This request remains unresolved and another change cannot be sent.</p>';
                if($view['recovery_ledger_sha256']!==null){echo '<form method="post" data-force-ssl-control-recover>';admin_action('provider_force_ssl_control_recover');echo '<input type="hidden" name="request_id" value="'.esc($view['id']).'"><input type="hidden" name="ledger_sha256" value="'.esc($view['recovery_ledger_sha256']).'"><p>The saved provider attempt reached its local record boundary. Restore only the missing local record, then separately read the flag. This does not resend the change or establish its effect.</p><label class="check"><input type="checkbox" name="reviewed" value="1" required> I reviewed this request and its saved attempt.</label>';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Restore local dispatch record</button></form>';}
                else echo '<p>There is no eligible finished attempt for recovery by this owner in the current context. Missing or unfinished provider records remain blocked. Ordinary Force SSL observations are available above; do not edit stored records to release the request.</p>';
            }
            elseif($view['status']==='not_sent')echo '<p>No provider dispatch was entered. Save a new Force SSL observation before a separate approval.</p>';
            elseif($view['status']==='observed')echo '<p>A later read reported the desired flag. The original request outcome remains unchanged. This does not prove the request caused the flag value.</p>';
            else{echo '<p>The provider response does not establish the effect of this change. A later failed, unavailable or different flag does not permit resending it.</p>';if($view['last_check'])echo '<p>Last follow-up: '.esc($view['last_check']['disposition']==='different'?'a different flag was reported':'no usable flag was reported').'.</p>';if($view['current_assignment']){echo '<form method="post" data-force-ssl-control-verify>';admin_action('provider_force_ssl_control_verify');echo '<input type="hidden" name="request_id" value="'.esc($view['id']).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn outline">Read the flag after this request</button><p class="hint">One new read, subject to the existing refresh limits. This does not resend the change.</p></form>';}}
            if($view['recovered_dispatch'])echo '<p data-force-ssl-control-recovered>The local dispatch record was restored from the saved attempt. The original provider result is unchanged; restoration did not resend the change or confirm its effect.</p>';
            if(!$view['current_assignment'])echo '<p>The original assignment or provider context is no longer current. The request remains saved for review.</p>';echo '</article>';
        }
        echo '<nav class="button-row" aria-label="Force SSL change history">';if($historyPage>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['force_ssl_change_history_page'=>$historyPage-1])).'#force-ssl-changes">Previous requests</a>';if((int)query('SELECT COUNT(*) FROM '.table('provider_force_ssl_changes'))->fetchColumn()>$historyPage*20&&$historyPage<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['force_ssl_change_history_page'=>$historyPage+1])).'#force-ssl-changes">More requests</a>';echo '</nav>';
    }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</section>';
}
